namespace sv_c539fbb3b30948358b32e1939851a3c8.Services;

public class AppointmentService
{
    public Task<List<string>> GetDoctorsAsync()
    {
        return Task.FromResult(new List<string>
        {
            "Dr. Smith",
            "Dr. Johnson",
            "Dr. Williams",
            "Dr. Patel"
        });
    }

    public Task<List<string>> GetAvailableTimeSlotsAsync(string doctor, DateTime date)
    {
        // Stub: return fixed slots regardless of doctor/date
        return Task.FromResult(new List<string>
        {
            "9:00 AM",
            "10:00 AM",
            "11:00 AM",
            "1:00 PM",
            "2:00 PM",
            "3:00 PM"
        });
    }

    /// <summary>
    /// Validates the patient/appointment data server-side.
    /// Returns a dictionary of field name → error message for any failures.
    /// An empty dictionary means validation passed.
    /// </summary>
    public Task<Dictionary<string, string>> ValidatePatientAsync(
        string email,
        string insuranceProvider,
        string doctor,
        string timeSlot)
    {
        var errors = new Dictionary<string, string>();

        // Reject email with outstanding balance
        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            errors[nameof(AppointmentModel.Email)] = "Account has outstanding balance";
        }

        // Reject self-pay with Dr. Smith
        if (insuranceProvider == "None" && doctor == "Dr. Smith")
        {
            errors[nameof(AppointmentModel.Doctor)] = "Selected doctor does not accept self-pay patients";
        }

        // Reject 10:00 AM as a race-condition taken slot
        if (timeSlot == "10:00 AM")
        {
            errors[nameof(AppointmentModel.TimeSlot)] = "This slot is no longer available";
        }

        return Task.FromResult(errors);
    }
}

using System.ComponentModel.DataAnnotations;

namespace sv_c539fbb3b30948358b32e1939851a3c8.Services;

public class AppointmentModel
{
    // Step 1
    [Required(ErrorMessage = "Patient name is required.")]
    public string PatientName { get; set; } = "";

    [Required(ErrorMessage = "Email is required.")]
    [EmailAddress(ErrorMessage = "Please enter a valid email address.")]
    public string Email { get; set; } = "";

    [Required(ErrorMessage = "Phone is required.")]
    public string Phone { get; set; } = "";

    [Required(ErrorMessage = "Please select an insurance provider.")]
    public string InsuranceProvider { get; set; } = "";

    // Step 2
    [Required(ErrorMessage = "Please select a doctor.")]
    public string Doctor { get; set; } = "";

    [Required(ErrorMessage = "Date is required.")]
    public DateTime? AppointmentDate { get; set; }

    [Required(ErrorMessage = "Please select a time slot.")]
    public string TimeSlot { get; set; } = "";

    [Required(ErrorMessage = "Reason for visit is required.")]
    [MaxLength(500, ErrorMessage = "Reason must be 500 characters or fewer.")]
    public string Reason { get; set; } = "";

    public IEnumerable<ValidationResult> ValidateDateInFuture()
    {
        if (AppointmentDate.HasValue && AppointmentDate.Value.Date <= DateTime.Today)
        {
            yield return new ValidationResult(
                "Appointment date must be in the future.",
                [nameof(AppointmentDate)]);
        }
    }
}

@page "/book-appointment"
@rendermode InteractiveServer
@using sv_c539fbb3b30948358b32e1939851a3c8.Services
@inject AppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h3 class="mb-4">Book a Medical Appointment</h3>

@if (isSubmitted)
{
    <div class="alert alert-success">
        <h4>Appointment Confirmed!</h4>
        <p>Thank you, <strong>@model.PatientName</strong>. Your appointment with <strong>@model.Doctor</strong> on
            <strong>@model.AppointmentDate?.ToString("MMMM d, yyyy")</strong> at <strong>@model.TimeSlot</strong> has been
            submitted.</p>
    </div>
}
else
{
    <EditForm EditContext="editContext" OnValidSubmit="HandleSubmit" FormName="bookAppointment">
        @* ───── STEP 1 ───── *@
        <fieldset>
            <legend>Step 1: Patient Information</legend>

            <div class="mb-3">
                <label for="patientName" class="form-label">Patient Name</label>
                <InputText id="patientName" class="form-control" @bind-Value="model.PatientName" />
                <ValidationMessage For="() => model.PatientName" />
            </div>

            <div class="mb-3">
                <label for="email" class="form-label">Email</label>
                <InputText id="email" class="form-control" @bind-Value="model.Email" />
                <ValidationMessage For="() => model.Email" />
            </div>

            <div class="mb-3">
                <label for="phone" class="form-label">Phone</label>
                <InputText id="phone" class="form-control" @bind-Value="model.Phone" />
                <ValidationMessage For="() => model.Phone" />
            </div>

            <div class="mb-3">
                <label for="insurance" class="form-label">Insurance Provider</label>
                <InputSelect id="insurance" class="form-select" @bind-Value="model.InsuranceProvider">
                    <option value="">-- Select --</option>
                    <option value="Aetna">Aetna</option>
                    <option value="BlueCross">BlueCross</option>
                    <option value="Cigna">Cigna</option>
                    <option value="UnitedHealth">UnitedHealth</option>
                    <option value="None">None</option>
                </InputSelect>
                <ValidationMessage For="() => model.InsuranceProvider" />
            </div>
        </fieldset>

        @if (!showStep2)
        {
            <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
                Next &rarr;
            </button>
        }

        @* ───── STEP 2 ───── *@
        @if (showStep2)
        {
            <fieldset class="mt-4">
                <legend>Step 2: Appointment Details</legend>

                <div class="mb-3">
                    <label for="doctor" class="form-label">Preferred Doctor</label>
                    <InputSelect id="doctor" class="form-select" @bind-Value="model.Doctor"
                        @bind-Value:after="OnDoctorOrDateChanged">
                        <option value="">-- Select --</option>
                        @foreach (var doc in doctors)
                        {
                            <option value="@doc">@doc</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => model.Doctor" />
                </div>

                <div class="mb-3">
                    <label for="date" class="form-label">Date</label>
                    <InputDate id="date" class="form-control" @bind-Value="model.AppointmentDate"
                        @bind-Value:after="OnDoctorOrDateChanged" />
                    <ValidationMessage For="() => model.AppointmentDate" />
                </div>

                <div class="mb-3">
                    <label for="timeSlot" class="form-label">Time Slot</label>
                    <InputSelect id="timeSlot" class="form-select" @bind-Value="model.TimeSlot">
                        <option value="">-- Select --</option>
                        @foreach (var slot in timeSlots)
                        {
                            <option value="@slot">@slot</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => model.TimeSlot" />
                </div>

                <div class="mb-3">
                    <label for="reason" class="form-label">Reason for Visit</label>
                    <InputTextArea id="reason" class="form-control" rows="3" @bind-Value="model.Reason" />
                    <ValidationMessage For="() => model.Reason" />
                </div>

                <button type="button" class="btn btn-secondary me-2" @onclick="BackToStep1">
                    &larr; Back
                </button>
                <button type="submit" class="btn btn-success" disabled="@isChecking">
                    @(isChecking ? "Checking Availability…" : "Check Availability & Submit")
                </button>
            </fieldset>
        }
    </EditForm>
}

@code {
    private AppointmentModel model = new();
    private EditContext editContext = default!;
    private ValidationMessageStore messageStore = default!;

    private bool showStep2;
    private bool isSubmitted;
    private bool isChecking;

    private List<string> doctors = new();
    private List<string> timeSlots = new();

    // Fields that belong to step 1 for partial validation
    private static readonly string[] Step1Fields =
        [nameof(AppointmentModel.PatientName), nameof(AppointmentModel.Email),
         nameof(AppointmentModel.Phone), nameof(AppointmentModel.InsuranceProvider)];

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(model);
        messageStore = new ValidationMessageStore(editContext);

        // Clear custom messages when a field changes so the user can retry
        editContext.OnFieldChanged += (_, args) =>
        {
            messageStore.Clear(args.FieldIdentifier);
            editContext.NotifyValidationStateChanged();
        };

        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        // Clear previous custom messages before re-validating
        messageStore.Clear();

        // Run DataAnnotations validation and check only step-1 fields
        editContext.Validate();

        var step1Valid = !Step1Fields
            .SelectMany(f => editContext.GetValidationMessages(
                new FieldIdentifier(model, f)))
            .Any();

        if (step1Valid)
        {
            showStep2 = true;
        }
    }

    private void BackToStep1()
    {
        showStep2 = false;
    }

    private async Task OnDoctorOrDateChanged()
    {
        if (!string.IsNullOrEmpty(model.Doctor) && model.AppointmentDate.HasValue)
        {
            timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(
                model.Doctor, model.AppointmentDate.Value);
        }
        else
        {
            timeSlots = new();
        }

        // Reset time slot when doctor/date changes since available slots may differ
        model.TimeSlot = "";
    }

    private async Task HandleSubmit()
    {
        messageStore.Clear();

        // Custom date-in-future validation
        foreach (var result in model.ValidateDateInFuture())
        {
            foreach (var member in result.MemberNames)
            {
                messageStore.Add(new FieldIdentifier(model, member), result.ErrorMessage!);
            }
        }

        if (editContext.GetValidationMessages().Any())
        {
            editContext.NotifyValidationStateChanged();
            return;
        }

        // Server-side business rules
        isChecking = true;
        try
        {
            var serverErrors = await AppointmentService.ValidatePatientAsync(
                model.Email, model.InsuranceProvider, model.Doctor, model.TimeSlot);

            if (serverErrors.Count > 0)
            {
                foreach (var (field, message) in serverErrors)
                {
                    messageStore.Add(new FieldIdentifier(model, field), message);
                }
                editContext.NotifyValidationStateChanged();
                return;
            }

            isSubmitted = true;
        }
        finally
        {
            isChecking = false;
        }
    }
}

