@code {
    private AppointmentModel model = new();
    private EditContext editContext = default!;
    private ValidationMessageStore messageStore = default!;

    private bool showStep2;
    private bool isSubmitted;
    private bool isChecking;

    private List<string> doctors = new();
    private List<string> timeSlots = new();

    // Fields that belong to step 1 for partial validation
    private static readonly string[] Step1Fields =
        [nameof(AppointmentModel.PatientName), nameof(AppointmentModel.Email),
         nameof(AppointmentModel.Phone), nameof(AppointmentModel.InsuranceProvider)];

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(model);
        messageStore = new ValidationMessageStore(editContext);

        // Clear custom messages when a field changes so the user can retry
        editContext.OnFieldChanged += (_, args) =>
        {
            messageStore.Clear(args.FieldIdentifier);
            editContext.NotifyValidationStateChanged();
        };

        doctors = await AppointmentService.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        // Clear previous custom messages before re-validating
        messageStore.Clear();

        // Run DataAnnotations validation and check only step-1 fields
        editContext.Validate();

        var step1Valid = !Step1Fields
            .SelectMany(f => editContext.GetValidationMessages(
                new FieldIdentifier(model, f)))
            .Any();

        if (step1Valid)
        {
            showStep2 = true;
        }
    }

    private void BackToStep1()
    {
        showStep2 = false;
    }

    private async Task OnDoctorOrDateChanged()
    {
        if (!string.IsNullOrEmpty(model.Doctor) && model.AppointmentDate.HasValue)
        {
            timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(
                model.Doctor, model.AppointmentDate.Value);
        }
        else
        {
            timeSlots = new();
        }

        // Reset time slot when doctor/date changes since available slots may differ
        model.TimeSlot = "";
    }

    private async Task HandleSubmit()
    {
        messageStore.Clear();

        // Custom date-in-future validation
        foreach (var result in model.ValidateDateInFuture())
        {
            foreach (var member in result.MemberNames)
            {
                messageStore.Add(new FieldIdentifier(model, member), result.ErrorMessage!);
            }
        }

        if (editContext.GetValidationMessages().Any())
        {
            editContext.NotifyValidationStateChanged();
            return;
        }

        // Server-side business rules
        isChecking = true;
        try
        {
            var serverErrors = await AppointmentService.ValidatePatientAsync(
                model.Email, model.InsuranceProvider, model.Doctor, model.TimeSlot);

            if (serverErrors.Count > 0)
            {
                foreach (var (field, message) in serverErrors)
                {
                    messageStore.Add(new FieldIdentifier(model, field), message);
                }
                editContext.NotifyValidationStateChanged();
                return;
            }

            isSubmitted = true;
        }
        finally
        {
            isChecking = false;
        }
    }
}

